  1	import { describe, it, expect } from 'vitest';
  2	import {
  3	  StrategicVisionSchema,
  4	  RepositoryEntrySchema,
  5	  RepositoryRegistrySchema,
  6	  type StrategicVision,
  7	  type RepositoryEntry,
  8	  type RepositoryRegistry,
  9	} from '../../src/schema/repository-registry.js';
 10	
 11	// ─── Fixtures ──────────────────────────────────────────────────────────────
 12	
 13	const validVision: StrategicVision = {
 14	  short_term: 'Stabilise the public API and achieve 90% test coverage.',
 15	  mid_term: 'Introduce plugin architecture and multi-tenant support.',
 16	  long_term: 'Become the de-facto standard for AI workflow orchestration.',
 17	};
 18	
 19	const nullVision: StrategicVision = {
 20	  short_term: null,
 21	  mid_term: null,
 22	  long_term: null,
 23	};
 24	
 25	const validEntry: RepositoryEntry = {
 26	  id: 'hcp-editor',
 27	  label: 'HCP Editor',
 28	  folder_names: ['hcp-editor', 'hcp-editor-dev'],
 29	  vision: validVision,
 30	  created_at: '2026-01-01T00:00:00Z',
 31	  last_modified: '2026-06-01T12:00:00Z',
 32	};
 33	
 34	const validRegistry: RepositoryRegistry = {
 35	  repositories: [validEntry],
 36	};
 37	
 38	// ─── StrategicVisionSchema ─────────────────────────────────────────────────
 39	
 40	describe('StrategicVisionSchema', () => {
 41	  it('accepts all three fields as non-empty strings', () => {
 42	    expect(StrategicVisionSchema.safeParse(validVision).success).toBe(true);
 43	  });
 44	
 45	  it('accepts all three fields as null (vision not yet authored)', () => {
 46	    expect(StrategicVisionSchema.safeParse(nullVision).success).toBe(true);
 47	  });
 48	
 49	  it('accepts a mixed state (some null, some non-null)', () => {
 50	    const mixed = { short_term: 'Ship v2.0.', mid_term: null, long_term: null };
 51	    expect(StrategicVisionSchema.safeParse(mixed).success).toBe(true);
 52	  });
 53	
 54	  it('rejects empty strings (empty is distinguishable from null)', () => {
 55	    expect(StrategicVisionSchema.safeParse({ ...nullVision, short_term: '' }).success).toBe(false);
 56	    expect(StrategicVisionSchema.safeParse({ ...validVision, mid_term: '' }).success).toBe(false);
 57	    expect(StrategicVisionSchema.safeParse({ ...validVision, long_term: '' }).success).toBe(false);
 58	  });
 59	
 60	  it('rejects when a required field is missing', () => {
 61	    const { short_term: _removed, ...missing } = validVision;
 62	    expect(StrategicVisionSchema.safeParse(missing).success).toBe(false);
 63	  });
 64	
 65	  it.each(['short_term', 'mid_term', 'long_term'] as const)(
 66	    'accepts field "%s" as null independently',
 67	    (field) => {
 68	      const input = { ...validVision, [field]: null };
 69	      expect(StrategicVisionSchema.safeParse(input).success).toBe(true);
 70	    }
 71	  );
 72	});
 73	
 74	// ─── RepositoryEntrySchema ─────────────────────────────────────────────────
 75	
 76	describe('RepositoryEntrySchema', () => {
 77	  it('accepts a fully populated valid entry', () => {
 78	    expect(RepositoryEntrySchema.safeParse(validEntry).success).toBe(true);
 79	  });
 80	
 81	  it('accepts an entry with a null vision (not yet authored)', () => {
 82	    const input = { ...validEntry, vision: nullVision };
 83	    expect(RepositoryEntrySchema.safeParse(input).success).toBe(true);
 84	  });
 85	
 86	  it('accepts an entry with a single folder name', () => {
 87	    const input = { ...validEntry, folder_names: ['hcp-editor'] };
 88	    expect(RepositoryEntrySchema.safeParse(input).success).toBe(true);
 89	  });
 90	
 91	  // ─── id validation (SLUG_REGEX) ───────────────────────────────────────────
 92	
 93	  it.each([
 94	    'hcp-editor',
 95	    'my_project',
 96	    'abc123',
 97	    'A',
 98	    'repo-name-2026',
 99	  ])('accepts valid id slug "%s"', (id) => {
100	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id }).success).toBe(true);

101	  });
102	
103	  it('rejects id that does not match SLUG_REGEX — starts with dash', () => {
104	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id: '-bad-slug' }).success).toBe(false);
105	  });
106	
107	  it('rejects id that does not match SLUG_REGEX — starts with underscore', () => {
108	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id: '_bad' }).success).toBe(false);
109	  });
110	
111	  it('rejects id that does not match SLUG_REGEX — contains slash (path traversal)', () => {
112	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id: 'my/repo' }).success).toBe(false);
113	  });
114	
115	  it('rejects id that does not match SLUG_REGEX — contains dot', () => {
116	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id: 'my.repo' }).success).toBe(false);
117	  });
118	
119	  it('rejects id that does not match SLUG_REGEX — contains space', () => {
120	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id: 'my repo' }).success).toBe(false);
121	  });
122	
123	  it('rejects id that does not match SLUG_REGEX — path traversal attempt', () => {
124	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, id: '../escape' }).success).toBe(false);
125	  });
126	
127	  // ─── Required field presence ───────────────────────────────────────────────
128	
129	  it.each(['id', 'label', 'folder_names', 'vision', 'created_at', 'last_modified'] as const)(
130	    'rejects when required field "%s" is missing',
131	    (field) => {
132	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
133	      const { [field]: _removed, ...rest } = validEntry as any;
134	      expect(RepositoryEntrySchema.safeParse(rest).success).toBe(false);
135	    }
136	  );
137	
138	  it('rejects an empty label', () => {
139	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, label: '' }).success).toBe(false);
140	  });
141	
142	  it('rejects an empty folder_names array', () => {
143	    expect(RepositoryEntrySchema.safeParse({ ...validEntry, folder_names: [] }).success).toBe(false);
144	  });
145	});
146	
147	// ─── RepositoryRegistrySchema ──────────────────────────────────────────────
148	
149	describe('RepositoryRegistrySchema', () => {
150	  it('accepts a registry with one valid entry', () => {
151	    expect(RepositoryRegistrySchema.safeParse(validRegistry).success).toBe(true);
152	  });
153	
154	  it('accepts a registry with multiple entries', () => {
155	    const secondEntry: RepositoryEntry = {
156	      ...validEntry,
157	      id: 'second-repo',
158	      label: 'Second Repo',
159	      folder_names: ['second-repo'],
160	    };
161	    const input = { repositories: [validEntry, secondEntry] };
162	    expect(RepositoryRegistrySchema.safeParse(input).success).toBe(true);
163	  });
164	
165	  it('accepts { "repositories": [] } (empty registry)', () => {
166	    expect(RepositoryRegistrySchema.safeParse({ repositories: [] }).success).toBe(true);
167	  });
168	
169	  it('rejects when repositories field is missing', () => {
170	    expect(RepositoryRegistrySchema.safeParse({}).success).toBe(false);
171	  });
172	
173	  it('rejects when repositories is not an array', () => {
174	    expect(RepositoryRegistrySchema.safeParse({ repositories: null }).success).toBe(false);
175	    expect(RepositoryRegistrySchema.safeParse({ repositories: 'not-an-array' }).success).toBe(false);
176	  });
177	
178	  it('rejects when repositories contains an invalid entry', () => {
179	    const invalidEntry = { ...validEntry, id: '-bad-id' };
180	    expect(RepositoryRegistrySchema.safeParse({ repositories: [invalidEntry] }).success).toBe(false);
181	  });
182	
183	  it('parses and returns typed RepositoryRegistry for a valid input', () => {
184	    const result = RepositoryRegistrySchema.safeParse(validRegistry);
185	    expect(result.success).toBe(true);
186	    if (result.success) {
187	      const data: RepositoryRegistry = result.data;
188	      expect(data.repositories).toHaveLength(1);
189	      expect(data.repositories[0].id).toBe('hcp-editor');
190	      expect(data.repositories[0].vision.short_term).toBe(validVision.short_term);
191	    }
192	  });
193	});
194	
195	// ─── TypeScript type exports (compile-time check) ──────────────────────────
196	// If the types are not exported, this file will fail to compile.
197	
198	describe('Exported TypeScript types', () => {
199	  it('StrategicVision type is exported and usable', () => {
200	    const v: StrategicVision = nullVision;
201	    expect(v.short_term).toBeNull();
202	  });
203	
204	  it('RepositoryEntry type is exported and usable', () => {
205	    const e: RepositoryEntry = validEntry;
206	    expect(e.id).toBe('hcp-editor');
207	  });
208	
209	  it('RepositoryRegistry type is exported and usable', () => {
210	    const r: RepositoryRegistry = validRegistry;
211	    expect(r.repositories).toHaveLength(1);
212	  });
213	});

